package org.sleepwell.app;

import org.junit.Test;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import static org.junit.Assert.*;

public class SmartLightRunTest {
    private SmartLightConfig config(boolean restore){return new SmartLightConfig("https://example.org","secret","light.bedroom",true,10,80,restore,1);}
    private static final class Fake implements SmartLightRun.Port {SmartLightRun.State state=new SmartLightRun.State(false,0,true);final List<Integer> writes=new ArrayList<>();boolean failRead,failSet;public SmartLightRun.State read()throws Exception{if(failRead)throw new Exception("private server/token");return state;}public void set(boolean on,int level)throws Exception{writes.add(on?level:0);if(failSet)throw new Exception("private server/token");state=new SmartLightRun.State(on,level,true);}}
    @Test public void progressesMonotonicallyAtBoundedIntervalsAndRestoresOff(){Fake f=new Fake();List<String> status=new ArrayList<>();SmartLightRun run=new SmartLightRun(config(true),f,()->true,status::add);run.tick(0);run.tick(1000);run.tick(300000);run.tick(600000);run.tick(900000);assertEquals(List.of(1,103,204),f.writes);run.close();run.close();run.tick(1000000);assertEquals(List.of(1,103,204,0),f.writes);assertEquals("Bedroom light restored",status.get(status.size()-1));}
    @Test public void doesNotDimExistingLightAndRestoresOriginalBrightness(){Fake f=new Fake();f.state=new SmartLightRun.State(true,90,true);SmartLightRun run=new SmartLightRun(config(true),f,()->true,s->{});run.tick(0);run.tick(600000);run.close();assertEquals(List.of(90,204,90),f.writes);}
    @Test public void alreadyAboveTargetIsUnchanged(){Fake f=new Fake();f.state=new SmartLightRun.State(true,250,true);SmartLightRun run=new SmartLightRun(config(true),f,()->true,s->{});run.tick(0);run.tick(600000);run.close();assertTrue(f.writes.isEmpty());}
    @Test public void manualOverrideStopsProgressAndAvoidsClobberingOnClose(){Fake f=new Fake();List<String> status=new ArrayList<>();SmartLightRun run=new SmartLightRun(config(true),f,()->true,status::add);run.tick(0);f.state=new SmartLightRun.State(true,80,true);run.tick(300000);f.state=new SmartLightRun.State(true,1,true);run.close();assertEquals(List.of(1),f.writes);assertTrue(status.stream().anyMatch(s->s.contains("changed elsewhere")));}
    @Test public void deadOwnerNeverStartsOrRestoresOnlyOwnPriorWrites(){Fake f=new Fake();AtomicBoolean alive=new AtomicBoolean(false);SmartLightRun run=new SmartLightRun(config(true),f,alive::get,s->{});run.tick(0);assertTrue(f.writes.isEmpty());run=new SmartLightRun(config(true),f,alive::get,s->{});alive.set(true);run.tick(0);alive.set(false);run.tick(5000);assertEquals(List.of(1,0),f.writes);}
    @Test public void explicitKeepSettingLeavesLampAtLastOwnedLevel(){Fake f=new Fake();SmartLightRun run=new SmartLightRun(config(false),f,()->true,s->{});run.tick(0);run.tick(600000);run.close();assertEquals(List.of(1,204),f.writes);assertTrue(f.state.on);}
    @Test public void unavailableOrNonDimmableLampCannotBlockOtherOutputs(){for(boolean readFailure:new boolean[]{true,false}){Fake f=new Fake();f.failRead=readFailure;f.state=new SmartLightRun.State(false,0,false);List<String> status=new ArrayList<>();SmartLightRun run=new SmartLightRun(config(true),f,()->true,status::add);run.tick(0);run.tick(5000);assertTrue(f.writes.isEmpty());assertEquals("Bedroom light unavailable; phone alarm continues",status.get(0));assertFalse(status.toString().contains("secret"));}}
    @Test public void failedWriteTerminatesAndReportsCleanupFailureSafely(){Fake f=new Fake();f.failSet=true;List<String> status=new ArrayList<>();SmartLightRun run=new SmartLightRun(config(true),f,()->true,status::add);run.tick(0);run.tick(5000);assertEquals(List.of(1),f.writes);assertTrue(status.get(0).contains("unavailable"));assertFalse(status.toString().contains("private"));}
    @Test public void configValidatesDestinationAndComputesClampedEnvelope(){SmartLightConfig c=config(true);c.validate();assertEquals(1,c.brightness(-1));assertEquals(204,c.brightness(600000));assertEquals(204,c.brightness(Long.MAX_VALUE));assertFalse(SmartLightConfig.empty().enabled);for(String url:List.of("http://example.org","https://a:b@example.org","https://example.org/?token=x","https://example.org/#x"))try{new SmartLightConfig(url,"secret","light.bedroom",true,10,80,true,1).validate();fail();}catch(IllegalArgumentException expected){}}
}
